  wire reset;
  input [7:0] w_in;
  wire [7:0] w_in;
  input [7:0] act_in;
  wire [7:0] act_in;
  output [7:0] act_out;
  reg [7:0] act_out = 8'h00;
  output [7:0] w_out;
  reg [7:0] w_out = 8'h00;
  output [31:0] acc;
  reg [31:0] acc = 32'd0;
  input psum_load;
  wire psum_load;
  input clk;
  wire clk;
  wire [15:0] \$1 ;
  wire [32:0] \$2 ;
  reg [7:0] \$3 ;
  reg [7:0] \$4 ;
  reg [31:0] \$5 ;
  (* init = 32'd0 *)
  wire [31:0] psum_out;
  always @(posedge clk)
    w_out <= \$4 ;
  always @(posedge clk)
    acc <= \$5 ;
  assign \$1  = $signed(act_in) * $signed(w_in);
  assign \$2  = $signed(acc) + $signed(\$1 );
  always @(posedge clk)
    act_out <= \$3 ;
  always @* begin
    \$4  = w_in;
    if (reset) begin
      \$4  = 8'h00;
    end
  end
  always @* begin
    (* full_case = 32'd1 *)
    if (psum_load) begin
      \$5  = 32'd0;
    end else begin
      \$5  = \$2 [31:0];
    end
    if (reset) begin
      \$5  = 32'd0;
    end
  end
  always @* begin
    \$3  = act_in;
    if (reset) begin
      \$3  = 8'h00;
    end
  end
  assign psum_out = acc;
endmodule

